import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
// Max reduction over dim=1 of a contiguous (B, D1, D2) float32 tensor.
// Optimization: split the reduction over D1 across 4 threads per output
// column (threadIdx.y), and give each thread a 4-way unrolled strided
// walk over its rows with 4 independent accumulators. This breaks the
// serial fmaxf dependency chain and puts 4 independent global loads in
// flight per thread (higher memory-level parallelism) for this
// bandwidth-bound streaming reduction, while threads with the same
// threadIdx.y still read consecutive columns to keep loads coalesced.
__global__ void max_reduce_dim1_kernel(const float* __restrict__ x,
                                       float* __restrict__ out,
                                       int D1, int D2) {
    const int b = blockIdx.y;
    const int j = blockIdx.x * blockDim.x + threadIdx.x;
    const int s = threadIdx.y;
    const int split = blockDim.y;
    __shared__ float smem[4][64];
    float m0 = -INFINITY;
    float m1 = -INFINITY;
    float m2 = -INFINITY;
    float m3 = -INFINITY;
    if (j < D2) {
        const float* q = x + (size_t)b * D1 * D2 + (size_t)s * D2 + j;
        const size_t stride = (size_t)split * D2;
        int i = s;
        for (; i + 3 * split < D1; i += 4 * split) {
            m0 = fmaxf(m0, __ldg(q));
            m1 = fmaxf(m1, __ldg(q + stride));
            m2 = fmaxf(m2, __ldg(q + 2 * stride));
            m3 = fmaxf(m3, __ldg(q + 3 * stride));
            q += 4 * stride;
        }
        for (; i < D1; i += split) {
            m0 = fmaxf(m0, __ldg(q));
            q += stride;
        }
    }
    float m = fmaxf(fmaxf(m0, m1), fmaxf(m2, m3));
    smem[s][threadIdx.x] = m;
    __syncthreads();
    if (s == 0 && j < D2) {
        #pragma unroll
        for (int k = 1; k < 4; ++k) m = fmaxf(m, smem[k][threadIdx.x]);
        out[(size_t)b * D2 + j] = m;
    }
}
torch::Tensor max_reduce_dim1(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "input must be CUDA");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(x.dim() == 3, "input must be 3D");
    auto xc = x.contiguous();
    const int B  = (int)xc.size(0);
    const int D1 = (int)xc.size(1);
    const int D2 = (int)xc.size(2);
    auto out = torch::empty({B, D2}, xc.options());
    dim3 block(64, 4);
    dim3 grid((D2 + (int)block.x - 1) / (int)block.x, B);
    max_reduce_dim1_kernel<<<grid, block, 0, at::cuda::getCurrentCUDAStream()>>>(
        xc.data_ptr<float>(), out.data_ptr<float>(), D1, D2);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return out;
}
"""
cpp_src = "torch::Tensor max_reduce_dim1(torch::Tensor x);"
_mod = load_inline(
    name="max_reduce_dim1_ext",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["max_reduce_dim1"],
    verbose=False,
)
class ModelNew(nn.Module):
    """
    Model that performs Max reduction over a specific dimension using a
    custom CUDA kernel (specialized for reduction over dim=1 of a 3D tensor).
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        dim = self.dim if self.dim >= 0 else self.dim + x.dim()
        if x.is_cuda and x.dim() == 3 and dim == 1 and x.dtype == torch.float32:
            return _mod.max_reduce_dim1(x)
        return torch.max(x, dim=self.dim)[0]

